1	import 'dart:convert';
2	
3	import 'package:fpdart/fpdart.dart';
4	
5	import '../../../../core/failure/failure.dart';
6	import '../../../../core/network/api_client.dart';
7	import '../../domain/entities/chat_stream_event.dart';
8	import '../models/chat_message_dto.dart';
9	import '../models/chat_session_dto.dart';
10	
11	/// The chat feature's one remote data source — non-streaming calls go
12	/// through `ApiClient`'s plain JSON methods exactly like
13	/// `EntriesRemoteDataSource`'s own `create`/`list`/`get`; [sendMessage]
14	/// alone goes through `ApiClient.postStream` and owns the one piece of
15	/// SSE-specific logic this story introduces: splitting the raw byte
16	/// stream into `event:`/`data:` blocks and mapping each into a
17	/// [ChatStreamEvent] (or an in-band [Failure]) — kept feature-local per
18	/// the Code Map, `ApiClient` itself knows nothing about the SSE grammar.
19	class ChatRemoteDataSource {
20	  ChatRemoteDataSource(this._apiClient);
21	
22	  final ApiClient _apiClient;
23	
24	  Future<Either<Failure, List<ChatSessionDto>>> listSessions() async {
25	    final result = await _apiClient.get('chat-sessions-list');
26	    return result.flatMap((json) {
27	      try {
28	        final data = json['data'] as List<dynamic>;
29	        return right(
30	          data
31	              .map(
32	                (item) => ChatSessionDto.fromJson(item as Map<String, dynamic>),
33	              )
34	              .toList(),
35	        );
36	      } catch (error) {
37	        // A 200 response that doesn't match the expected shape is a
38	        // client-side parse failure, never a backend-sent code — same
39	        // RNF09 rationale `EntriesRemoteDataSource`'s own calls document.
40	        return left(Failure.malformedResponse(message: error.toString()));
41	      }
42	    });
43	  }
44	
45	  /// Sends no `title` (Boundaries: "`chat-sessions-create` with no
46	  /// title") — the contract's own `title` field is optional
47	  /// (`openapi.yaml`), an empty body is valid.
48	  Future<Either<Failure, ChatSessionDto>> createSession() async {
49	    final result = await _apiClient.post('chat-sessions-create', data: const {});
50	    return result.flatMap((json) {
51	      try {
52	        final data = json['data'] as Map<String, dynamic>;
53	        return right(ChatSessionDto.fromJson(data));
54	      } catch (error) {
55	        return left(Failure.malformedResponse(message: error.toString()));
56	      }
57	    });
58	  }
59	
60	  Future<Either<Failure, List<ChatMessageDto>>> listMessages(
61	    String sessionId,
62	  ) async {
63	    final result = await _apiClient.get(
64	      'chat-messages-list',
65	      pathParams: [sessionId],
66	    );
67	    return result.flatMap((json) {
68	      try {
69	        final data = json['data'] as List<dynamic>;
70	        return right(
71	          data
72	              .map(
73	                (item) => ChatMessageDto.fromJson(item as Map<String, dynamic>),
74	              )
75	              .toList(),
76	        );
77	      } catch (error) {
78	        return left(Failure.malformedResponse(message: error.toString()));
79	      }
80	    });
81	  }
82	
83	  /// Consumes `ApiClient.postStream('chat-messages-send', pathParams:
84	  /// [sessionId], data: {'content': content})` chunk by chunk, buffering
85	  /// raw text until a full `\n\n`-terminated SSE event block is
86	  /// available, then hands each complete block to [_parseEvent].
87	  ///
88	  /// Terminal handling (Design Notes/I/O matrix):
89	  /// - An upstream `Left` (an offline/timeout/etc. failure from the
90	  ///   underlying HTTP call itself, surfaced by `ApiClient.postStream`) is
91	  ///   forwarded as-is and ends the stream immediately — covers "Send
92	  ///   while offline" (an immediate `Left(Failure.networkOffline)`, never
93	  ///   queued) and any other transport-level failure.
94	  /// - A parsed `done` event or an in-band `error` event (mapped via
95	  ///   [Failure.fromCode]) both end the stream right after being emitted
96	  ///   — the backend's own SSE ordering guarantees neither is followed by
97	  ///   anything else worth reading.
98	  /// - If the underlying byte stream simply ends (no exception, no
99	  ///   `done`/`error` event ever parsed) — a mid-stream drop — a single
100	  ///   trailing `Left(Failure.networkTimeout)` is emitted, since the
101	  ///   closed, 13-code taxonomy has no dedicated "dropped stream" code
102	  ///   (Design Notes).
103	  Stream<Either<Failure, ChatStreamEvent>> sendMessage(
104	    String sessionId,
105	    String content,
106	  ) async* {
107	    var buffer = '';
108	    await for (final chunkResult in _apiClient.postStream(
109	      'chat-messages-send',
110	      pathParams: [sessionId],
111	      data: {'content': content},
112	    )) {
113	      final upstreamFailure = chunkResult.fold((f) => f, (_) => null);
114	      if (upstreamFailure != null) {
115	        yield left(upstreamFailure);
116	        return;
117	      }
118	      final chunk = chunkResult.fold((_) => '', (s) => s);
119	      buffer += chunk.replaceAll('\r\n', '\n');
120	
121	      var separatorIndex = buffer.indexOf('\n\n');
122	      while (separatorIndex != -1) {
123	        final rawEvent = buffer.substring(0, separatorIndex);
124	        buffer = buffer.substring(separatorIndex + 2);
125	        if (rawEvent.trim().isNotEmpty) {
126	          final parsed = _parseEvent(rawEvent);
127	          if (parsed != null) {
128	            final isDone = parsed.fold((_) => false, (e) => e is ChatDoneEvent);
129	            final isFailure = parsed.isLeft();
130	            yield parsed;
131	            // A `done`/in-band-error exit is a clean terminal event, not
132	            // a drop — return directly, skipping the trailing
133	            // mid-stream-drop failure below.
134	            if (isDone || isFailure) {
135	              return;
136	            }
137	          }
138	        }
139	        separatorIndex = buffer.indexOf('\n\n');
140	      }
141	    }
142	    // Reached only if the byte stream ended on its own (no exception, no
143	    // `done`/`error` event ever parsed) — a mid-stream drop.
144	    yield left(
145	      const Failure.networkTimeout(
146	        message: 'Connection closed before the response completed',
147	      ),
148	    );
149	  }
150	
151	  /// Parses one complete, blank-line-delimited SSE event block into a
152	  /// [ChatStreamEvent] (`Right`), an in-band failure (`Left`), or `null`
153	  /// when the block should simply be skipped — a `context` event
154	  /// (Boundaries: "received and discarded", never surfaced as a
155	  /// [ChatStreamEvent]) or any event name this client doesn't recognize
156	  /// (forward-compatible: an unknown future event type is ignored rather
157	  /// than treated as malformed). Any JSON-decode failure, or a decoded
158	  /// payload missing the field a known event name requires, maps to
159	  /// [Failure.malformedResponse] (Design Notes: "anything that fails to
160	  /// parse as expected becomes `Failure.malformedResponse`, never a
161	  /// crash") — never a thrown exception escaping into [sendMessage]'s own
162	  /// `async*` body.
163	  Either<Failure, ChatStreamEvent>? _parseEvent(String rawEvent) {
164	    String? eventName;
165	    final dataLines = <String>[];
166	    for (final line in rawEvent.split('\n')) {
167	      if (line.startsWith('event:')) {
168	        eventName = line.substring('event:'.length).trim();
169	      } else if (line.startsWith('data:')) {
170	        var value = line.substring('data:'.length);
171	        if (value.startsWith(' ')) {
172	          value = value.substring(1);
173	        }
174	        dataLines.add(value);
175	      }
176	    }
177	    if (eventName == null) {
178	      return null;
179	    }
180	    final dataStr = dataLines.join('\n');
181	
182	    switch (eventName) {
183	      case 'message_created':
184	        try {
185	          final json = jsonDecode(dataStr) as Map<String, dynamic>;
186	          return right(ChatMessageCreatedEvent(json['id'] as String));
187	        } catch (error) {
188	          return left(
189	            Failure.malformedResponse(
190	              message: 'malformed message_created event: $error',
191	            ),
192	          );
193	        }
194	      case 'context':
195	        // Boundaries: "never rendering the SSE `context` event's
196	        // retrieval/citation data" — received and discarded.
197	        return null;
198	      case 'token':
199	        try {
200	          final json = jsonDecode(dataStr) as Map<String, dynamic>;
201	          return right(ChatTokenEvent(json['delta'] as String));
202	        } catch (error) {
203	          return left(
204	            Failure.malformedResponse(
205	              message: 'malformed token event: $error',
206	            ),
207	          );
208	        }
209	      case 'done':
210	        return right(const ChatDoneEvent());
211	      case 'error':
212	        try {
213	          final json = jsonDecode(dataStr) as Map<String, dynamic>;
214	          final code = json['code'] as String;
215	          final message = json['message'];
216	          return left(
217	            Failure.fromCode(
218	              code,
219	              message is String ? message : 'Unknown error',
220	            ),
221	          );
222	        } catch (error) {
223	          return left(
224	            Failure.malformedResponse(
225	              message: 'malformed error event: $error',
226	            ),
227	          );
228	        }
229	      default:
230	        // Forward-compatible: an event name this client doesn't
231	        // recognize is skipped, not treated as malformed.
232	        return null;
233	    }
234	  }
235	}
