import 'dart:async';

import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:fpdart/fpdart.dart';

import '../../../../core/failure/failure.dart';
import '../../domain/entities/chat_message.dart';
import '../../domain/entities/chat_session.dart';
import '../../domain/entities/chat_stream_event.dart';
import '../../domain/repositories/chat_repository.dart';
import 'chat_state.dart';

/// Drives `ChatScreen` — a DI `lazySingleton` (Code Map, mirroring
/// `MeusRegistrosCubit`): long-lived, so returning to Home/Chat within the
/// same app session never re-bootstraps the session/history it already
/// loaded (`init()`'s own no-op guard below).
class ChatCubit extends Cubit<ChatState> {
  ChatCubit(this._repository) : super(const ChatBootstrapLoading());

  final ChatRepository _repository;

  StreamSubscription<Either<Failure, ChatStreamEvent>>? _sendSubscription;

  /// Monotonic counter behind every locally generated [ChatUiMessage.id]
  /// (Code Map) — never the server's own message id (see `ChatStreamEvent`'s
  /// own doc on why `message_created`'s id goes unused here).
  int _localIdCounter = 0;

  /// Whether a send is actively in flight right now — tracked locally
  /// rather than by scanning [ChatState.messages] for a persisted
  /// `streaming` status, since a message loaded from history/cache can
  /// legitimately carry that same status (e.g. one left over from an
  /// earlier dropped response, the I/O matrix's own scenario) without a
  /// send actually being in progress; scanning for it would permanently
  /// disable the composer in that case.
  bool _isSending = false;

  /// An in-flight bootstrap, if any — reused by a concurrent `init()` call
  /// instead of starting a second bootstrap, so two near-simultaneous
  /// callers (e.g. two mounts before the first resolves) never both
  /// observe "no sessions" and both call `createSession()` (Boundaries:
  /// "silently ensure *one* Chat Session exists").
  Future<void>? _initFuture;

  /// Boundaries: "On opening Home/Chat, silently ensure one Chat Session
  /// exists (reuse the most recent from `chat-sessions-list`, else
  /// `chat-sessions-create` with no title)". A no-op once already
  /// [ChatReady] — `ChatScreen.initState()` calls this unconditionally on
  /// every mount, but a `lazySingleton` cubit may already be bootstrapped
  /// from an earlier visit.
  Future<void> init() {
    if (state is ChatReady || isClosed) {
      return Future.value();
    }
    return _initFuture ??= _bootstrap().whenComplete(() => _initFuture = null);
  }

  Future<void> _bootstrap() async {
    emit(const ChatBootstrapLoading());

    final sessionsResult = await _repository.listSessions();
    if (isClosed) {
      return;
    }
    final Either<Failure, ChatSession> sessionResult = await sessionsResult
        .match((failure) async => left(failure), (sessions) async {
          if (sessions.isEmpty) {
            return _repository.createSession();
          }
          // "reuse the most recent" — defensively re-sorts rather than
          // trusting `listSessions()`'s own ordering (its offline-cache
          // fallback already sorts `updatedAt` desc, but the live
          // server response's own ordering isn't documented either
          // way).
          final mostRecent = [...sessions]
            ..sort((a, b) => b.updatedAt.compareTo(a.updatedAt));
          return right(mostRecent.first);
        });
    if (isClosed) {
      return;
    }

    await sessionResult.match(
      (failure) async {
        if (!isClosed) {
          emit(ChatBootstrapError(failure));
        }
      },
      (session) async {
        final messagesResult = await _repository.listMessages(session.id);
        if (isClosed) {
          return;
        }
        messagesResult.match(
          (failure) => emit(ChatBootstrapError(failure)),
          (messages) => emit(
            ChatReady(
              sessionId: session.id,
              messages: messages.map(_fromDomain).toList(),
            ),
          ),
        );
      },
    );
  }

  ChatUiMessage _fromDomain(ChatMessage message) => ChatUiMessage(
    id: message.id,
    role: message.role,
    content: message.content,
    status: message.status,
  );

  /// Boundaries: optimistic user bubble, then subscribes to
  /// `ChatRepository.sendMessage`'s own stream, appending tokens as they
  /// arrive and finalizing/failing the AI bubble on `done`/any `Left` —
  /// the bubble's own [ChatUiMessage.content] is never cleared on failure
  /// (I/O matrix), only its [ChatUiMessage.status] changes.
  ///
  /// A no-op while [state] isn't [ChatReady] (bootstrap still in flight
  /// or failed — the composer is disabled in that case anyway), while
  /// [content] is blank once trimmed, or while [_isSending] is already
  /// true — this story never races two concurrent sends against the one
  /// in-memory session (Boundaries: no offline lock/composer-disable UI
  /// of its own exists yet, Story 6.3's job, so this guard is the one
  /// thing standing in for it here). Deliberately not keyed off any
  /// loaded message's persisted `streaming` status — a message restored
  /// from history/cache can legitimately carry that status without a
  /// send actually being in flight (I/O matrix: mid-stream drop).
  Future<void> sendMessage(String content) async {
    final trimmed = content.trim();
    if (trimmed.isEmpty) {
      return;
    }
    final current = state;
    if (current is! ChatReady) {
      return;
    }
    if (_isSending) {
      return;
    }
    _isSending = true;

    final userMessage = ChatUiMessage(
      id: _nextLocalId(),
      role: ChatMessageRole.user,
      content: trimmed,
      status: ChatMessageStatus.complete,
    );
    final aiMessage = ChatUiMessage(
      id: _nextLocalId(),
      role: ChatMessageRole.assistant,
      content: '',
      status: ChatMessageStatus.streaming,
    );
    emit(
      current.copyWith(
        messages: [...current.messages, userMessage, aiMessage],
        isSending: true,
      ),
    );

    await _sendSubscription?.cancel();
    final completer = Completer<void>();
    _sendSubscription = _repository
        .sendMessage(current.sessionId, trimmed)
        .listen(
          (event) {
            event.match(
              (failure) => _markFailed(aiMessage.id),
              (streamEvent) => _applyStreamEvent(aiMessage.id, streamEvent),
            );
          },
          onError: (Object _, StackTrace _) {
            // RNF09: no exception escapes the cubit — a stream-level
            // error (shouldn't happen, `ChatRemoteDataSource.sendMessage`
            // never lets one through unmapped) still only fails the
            // bubble, never crashes.
            _markFailed(aiMessage.id);
            _finishSending();
            if (!completer.isCompleted) {
              completer.complete();
            }
          },
          onDone: () {
            _finishSending();
            if (!completer.isCompleted) {
              completer.complete();
            }
          },
          cancelOnError: false,
        );
    await completer.future;
  }

  /// Clears both the internal re-entrancy guard and the UI-facing
  /// [ChatReady.isSending] signal once a send's stream has ended (`done`,
  /// an in-band error, or a stream-level error) — the single place both
  /// flip back together.
  void _finishSending() {
    _isSending = false;
    if (isClosed) {
      return;
    }
    final current = state;
    if (current is ChatReady) {
      emit(current.copyWith(isSending: false));
    }
  }

  void _applyStreamEvent(String aiMessageId, ChatStreamEvent event) {
    if (isClosed) {
      return;
    }
    final current = state;
    if (current is! ChatReady) {
      return;
    }
    switch (event) {
      case ChatMessageCreatedEvent():
        // Design Notes: the persisted *user*-message id — no UI-facing
        // use yet in this story (Story 6.3's retry call is the first
        // consumer).
        break;
      case ChatTokenEvent(delta: final delta):
        emit(
          current.copyWith(
            messages: [
              for (final message in current.messages)
                if (message.id == aiMessageId)
                  message.copyWith(content: message.content + delta)
                else
                  message,
            ],
          ),
        );
      case ChatDoneEvent():
        emit(
          current.copyWith(
            messages: [
              for (final message in current.messages)
                if (message.id == aiMessageId)
                  message.copyWith(status: ChatMessageStatus.complete)
                else
                  message,
            ],
          ),
        );
    }
  }

  /// I/O matrix: "Mid-stream drop"/"In-band `error` event" — marks the one
  /// bubble `failed`, by id, leaving its already-streamed-in text exactly
  /// as-is (never cleared, Boundaries).
  void _markFailed(String aiMessageId) {
    if (isClosed) {
      return;
    }
    final current = state;
    if (current is! ChatReady) {
      return;
    }
    emit(
      current.copyWith(
        messages: [
          for (final message in current.messages)
            if (message.id == aiMessageId)
              message.copyWith(status: ChatMessageStatus.failed)
            else
              message,
        ],
      ),
    );
  }

  String _nextLocalId() => 'local-${_localIdCounter++}';

  @override
  Future<void> close() {
    _sendSubscription?.cancel();
    return super.close();
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';

import '../../../../core/design_tokens.dart';
import '../../../../core/di/injection_container.dart';
import '../../../../core/failure/failure.dart';
import '../../../../core/widgets/app_drawer.dart';
import '../../../capture/presentation/cubit/audio_entry_cubit.dart';
import '../../../capture/presentation/cubit/photo_entry_cubit.dart';
import '../../../capture/presentation/cubit/text_entry_cubit.dart';
import '../../../capture/presentation/widgets/insertion_modal.dart';
import '../cubit/chat_cubit.dart';
import '../cubit/chat_state.dart';
import '../widgets/chat_bubble.dart';

/// Tela 1 — Home/Chat, RF04's first real (non-placeholder) screen: the
/// same dark-green header + drawer chrome the deleted
/// `HomeChatPlaceholderScreen` used, now with a real message list and
/// composer. [cubit] is injected rather than resolved internally
/// (`sl<ChatCubit>()` stays the router's own job, Code Map), so a test can
/// pass a fake-repository-backed instance directly.
class ChatScreen extends StatefulWidget {
  const ChatScreen({required this.cubit, super.key});

  final ChatCubit cubit;

  @override
  State<ChatScreen> createState() => _ChatScreenState();
}

class _ChatScreenState extends State<ChatScreen> {
  final _textController = TextEditingController();
  final _scrollController = ScrollController();

  @override
  void initState() {
    super.initState();
    // `ChatCubit.init()`'s own no-op guard makes this safe to call on
    // every mount (Boundaries: "silently ensure one Chat Session exists").
    widget.cubit.init();
  }

  @override
  void dispose() {
    _textController.dispose();
    _scrollController.dispose();
    super.dispose();
  }

  void _send() {
    final text = _textController.text;
    if (text.trim().isEmpty) {
      return;
    }
    widget.cubit.sendMessage(text);
    _textController.clear();
  }

  /// Only jumps to the bottom when the view was already there (or close
  /// to it) *before* this update, or hasn't attached to a scrollable yet
  /// (the very first history render) — otherwise a user who deliberately
  /// scrolled up to reread earlier history would get yanked back down on
  /// every single streamed token.
  void _scrollToBottomSoon() {
    if (_scrollController.hasClients) {
      final position = _scrollController.position;
      const nearBottomThreshold = 80.0;
      final wasNearBottom =
          position.maxScrollExtent - position.pixels <= nearBottomThreshold;
      if (!wasNearBottom) {
        return;
      }
    }
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (_scrollController.hasClients) {
        _scrollController.jumpTo(_scrollController.position.maxScrollExtent);
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    return BlocProvider<ChatCubit>.value(
      value: widget.cubit,
      child: Scaffold(
        backgroundColor: DesignTokens.colorSurfaceBg,
        drawer: const AppDrawer(),
        // Boundaries: "heavier drawer scrim rgba(36,31,25,.4)" — overrides
        // `Scaffold`'s own default barrier, same convention the deleted
        // `HomeChatPlaceholderScreen` already used.
        drawerScrimColor: DesignTokens.colorScrimHeavy,
        body: Column(
          children: [
            const _ChatHeader(),
            Expanded(
              child: BlocConsumer<ChatCubit, ChatState>(
                listener: (context, state) {
                  if (state is ChatReady) {
                    _scrollToBottomSoon();
                  }
                },
                builder: (context, state) => switch (state) {
                  ChatBootstrapLoading() => const Center(
                    child: CircularProgressIndicator(
                      color: DesignTokens.colorPrimary,
                    ),
                  ),
                  ChatBootstrapError(failure: final failure) =>
                    _ChatBootstrapErrorView(failure: failure),
                  ChatReady(messages: final messages) => ListView.builder(
                    controller: _scrollController,
                    padding: DesignTokens.screenPadding,
                    itemCount: messages.length,
                    itemBuilder: (context, index) => ChatBubble(
                      key: ValueKey(messages[index].id),
                      message: messages[index],
                    ),
                  ),
                },
              ),
            ),
            _ChatComposer(controller: _textController, onSend: _send),
          ],
        ),
      ),
    );
  }
}

/// The same dark-green header + ☰-opens-drawer wiring the deleted
/// `HomeChatPlaceholderScreen` used — moved here verbatim rather than
/// shared from a common widget, since that screen is deleted wholesale
/// (Code Map) and no third screen needs this exact header yet.
class _ChatHeader extends StatelessWidget {
  const _ChatHeader();

  @override
  Widget build(BuildContext context) {
    return Container(
      color: DesignTokens.colorPrimary,
      padding: DesignTokens.navHeaderPadding,
      child: Builder(
        builder: (context) => Row(
          children: [
            GestureDetector(
              onTap: () => Scaffold.of(context).openDrawer(),
              child: const Icon(
                Icons.menu,
                size: DesignTokens.navMenuIconSize,
                color: DesignTokens.colorOnPrimary,
              ),
            ),
            Expanded(
              child: Text(
                'Cerne',
                textAlign: TextAlign.center,
                style: DesignTokens.textTitleLg.copyWith(
                  color: DesignTokens.colorOnPrimary,
                ),
              ),
            ),
            const SizedBox(width: DesignTokens.navMenuIconSize),
          ],
        ),
      ),
    );
  }
}

/// I/O matrix: "Bootstrap failure" — a generic error state, not an
/// infinite spinner; no retry action exists yet (Boundaries: the
/// retry-tap action belongs to Story 6.2–6.5).
class _ChatBootstrapErrorView extends StatelessWidget {
  const _ChatBootstrapErrorView({required this.failure});

  final Failure failure;

  @override
  Widget build(BuildContext context) {
    return Center(
      child: Padding(
        padding: DesignTokens.screenPadding,
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            const Icon(
              Icons.error_outline,
              size: DesignTokens.spacing2xl,
              color: DesignTokens.colorError,
            ),
            const SizedBox(height: DesignTokens.spacingMd),
            Text(
              'Não foi possível carregar a conversa',
              textAlign: TextAlign.center,
              style: DesignTokens.textHeadlineMd.copyWith(
                color: DesignTokens.colorTextPrimary,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

/// The composer row — "+" (`InsertionModal.show`, unchanged), a text
/// field (placeholder "Escreva uma mensagem...") and a send icon.
/// Disabled as a whole while the bootstrap hasn't resolved yet or while
/// an AI bubble is still `streaming` (Code Map/`ChatCubit.sendMessage`'s
/// own same-shaped guard) — never a dedicated offline banner/lock, that's
/// Story 6.3's job (Boundaries).
class _ChatComposer extends StatelessWidget {
  const _ChatComposer({required this.controller, required this.onSend});

  final TextEditingController controller;
  final VoidCallback onSend;

  @override
  Widget build(BuildContext context) {
    return BlocBuilder<ChatCubit, ChatState>(
      builder: (context, state) {
        final canSend = state is ChatReady && !state.isSending;
        return SafeArea(
          top: false,
          child: Padding(
            padding: DesignTokens.screenPadding,
            child: Row(
              children: [
                Semantics(
                  button: true,
                  label: 'Adicionar registro',
                  excludeSemantics: true,
                  child: IconButton(
                    onPressed: () => InsertionModal.show(
                      context,
                      cubit: sl<TextEntryCubit>(),
                      audioCubit: sl<AudioEntryCubit>(),
                      photoCubit: sl<PhotoEntryCubit>(),
                    ),
                    icon: const Icon(Icons.add, color: DesignTokens.colorPrimary),
                  ),
                ),
                Expanded(
                  child: TextField(
                    controller: controller,
                    enabled: canSend,
                    // `chat-messages-send`'s own request schema caps
                    // `content` at 8000 characters (openapi.yaml) — a
                    // client-side cap surfaces that limit directly
                    // instead of letting an over-length message fail
                    // only after a round trip, indistinguishable from a
                    // dropped connection.
                    maxLength: 8000,
                    textInputAction: TextInputAction.send,
                    onSubmitted: canSend ? (_) => onSend() : null,
                    style: DesignTokens.textBodyLg.copyWith(
                      color: DesignTokens.colorTextPrimary,
                    ),
                    decoration: InputDecoration(
                      hintText: 'Escreva uma mensagem...',
                      counterText: '',
                      contentPadding: DesignTokens.textFieldContentPadding,
                      border: const OutlineInputBorder(
                        borderRadius: BorderRadius.all(
                          Radius.circular(DesignTokens.radiusFull),
                        ),
                        borderSide: BorderSide(
                          color: DesignTokens.colorBorder,
                          width: DesignTokens.borderWidthDefault,
                        ),
                      ),
                      enabledBorder: const OutlineInputBorder(
                        borderRadius: BorderRadius.all(
                          Radius.circular(DesignTokens.radiusFull),
                        ),
                        borderSide: BorderSide(
                          color: DesignTokens.colorBorder,
                          width: DesignTokens.borderWidthDefault,
                        ),
                      ),
                      focusedBorder: const OutlineInputBorder(
                        borderRadius: BorderRadius.all(
                          Radius.circular(DesignTokens.radiusFull),
                        ),
                        borderSide: BorderSide(
                          color: DesignTokens.colorPrimary,
                          width: DesignTokens.borderWidthEmphasis,
                        ),
                      ),
                    ),
                  ),
                ),
                Semantics(
                  button: true,
                  label: 'Enviar mensagem',
                  excludeSemantics: true,
                  child: IconButton(
                    onPressed: canSend ? onSend : null,
                    icon: Icon(
                      Icons.send,
                      color: canSend
                          ? DesignTokens.colorPrimary
                          : DesignTokens.colorTextSecondary,
                    ),
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }
}

